  "note_cle": "Clé du PDF (« AI corrected », non officielle) revérifiée.",
  "question_en": "Among the following propositions, which are correct:",
  "propositions_en": {
   "A": "At 0 °C, the enzyme is denatured, which explains a near-zero reaction rate.",
   "B": "At 100 °C, the enzyme is reversibly inhibited, because if cooled it recovers its activity.",
   "C": "The optimum temperature of human enzymes is approximately 37 °C.",
   "D": "Certain gastric enzymes have an optimum pH close to 10.",
   "E": "Most enzymes have an optimum pH close to 7."
  }
