  "question": "À propos de la vitesse maximale (Vmax) et du Km :",
  "propositions": {
   "A": "La Vmax reflète l'affinité de l'enzyme pour le substrat",
   "B": "La Vmax est déterminée lorsque la concentration en substrat est saturante",
   "C": "Le Km correspond à la concentration en substrat permettant à l'enzyme de fonctionner à la moitié de la Vmax",
   "D": "Plus la valeur du Km est élevée, plus l'affinité de l'enzyme pour son substrat est grande",
   "E": "Le Km et la Vmax sont déterminés avec une grande précision par la droite de Lineweaver et Burk"
  },
  "question_fr": "À propos de la vitesse maximale (Vmax) et du Km :",
  "propositions_fr": {
   "A": "La Vmax reflète l'affinité de l'enzyme pour le substrat",
   "B": "La Vmax est déterminée lorsque la concentration en substrat est saturante",
   "C": "Le Km correspond à la concentration en substrat permettant à l'enzyme de fonctionner à la moitié de la Vmax",
   "D": "Plus la valeur du Km est élevée, plus l'affinité de l'enzyme pour son substrat est grande",
   "E": "Le Km et la Vmax sont déterminés avec une grande précision par la droite de Lineweaver et Burk"
  },
